SELECT DATE_FORMAT(end_date, 'yyyy-MM') AS end_month, YEAR(end_date) AS end_year, plan, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled, MAX(end_date) AS latest_end_date FROM subscriptions WHERE status IN ('PAUSED', 'EXPIRED', 'ACTIVE') AND plan IN ('premium', 'basic', 'standard') GROUP BY DATE_FORMAT(end_date, 'yyyy-MM'), YEAR(end_date), plan
